"use client";

import Link from "next/link";

const handleBookCall = () => {
  window.open("https://calendly.com/akashsomasalle/30min", "_blank", "noopener,noreferrer");
};

export default function Header() {
  return (
    <nav className="w-full h-16 shrink-0 flex justify-center border-b border-gray-300 font-[cursive] text-xl">
      <div className="w-full max-w-5xl flex justify-between items-center p-3 px-5">
        <Link href="/" className="font-semibold">
          PEN3D
        </Link>

        <button
          onClick={handleBookCall}
          className="rounded-full bg-black px-6 py-2 text-sm font-medium text-white shadow-lg transition hover:bg-gray-800 cursor-pointer"
        >
          Book a call
        </button>
      </div>
    </nav>
  );
}